classDiagram
    class Iterable {
        +Symbol.iterator() Iterator
    }
    class Iterator {
        +next() IteratorResult
        +return(value) IteratorResult
        +throw(error) IteratorResult
    }
    class IteratorResult {
        +value any
        +done boolean
    }
    class ConcreteCollection {
        -items any[]
        +Symbol.iterator() Iterator
    }
    class ConcreteIterator {
        -index number
        +next() IteratorResult
    }
    Iterable <|.. ConcreteCollection
    Iterator <|.. ConcreteIterator
    ConcreteCollection --> ConcreteIterator : creates
    ConcreteIterator --> IteratorResult : returns

