// ── 1. Manual iterator: NumberRange ─────────────────────────────
class NumberRange {
  constructor(start, end) {
    this.start = start;
    this.end   = end;
  }

  [Symbol.iterator]() {
    let current = this.start;
    const end   = this.end;
    // Return a plain object — the ConcreteIterator
    return {
      next() {
        if (current <= end) {
          return { value: current++, done: false };
        }
        return { value: undefined, done: true };
      }
    };
  }
}

const range = new NumberRange(1, 5);

// All of these work because NumberRange is iterable:
for (const n of range) process.stdout.write(n + ' ');  // 1 2 3 4 5
console.log();
console.log([...range]);          // [1, 2, 3, 4, 5]
console.log(Array.from(range));   // [1, 2, 3, 4, 5]
const [first, second] = range;
console.log(first, second);       // 1 2

// Each call to [Symbol.iterator]() returns a FRESH iterator:
const iter1 = range[Symbol.iterator]();
const iter2 = range[Symbol.iterator]();
console.log(iter1.next()); // { value: 1, done: false }
console.log(iter2.next()); // { value: 1, done: false }  — independent!
console.log(iter1.next()); // { value: 2, done: false }

// ── 2. Self-referential iterator (iterable + iterator in one) ───
const countdown = {
  value: 3,
  next() {
    if (this.value > 0) return { value: this.value--, done: false };
    return { value: undefined, done: true };
  },
  [Symbol.iterator]() { return this; }  // returns itself
};

for (const n of countdown) process.stdout.write(n + ' ');  // 3 2 1
console.log();
// WARNING: countdown is now exhausted! next() still returns done:true
// Cannot reuse — this is a single-use iterator

// ── Generator basics ────────────────────────────────────────────
function* range(start, end, step = 1) {
  for (let i = start; i <= end; i += step) {
    yield i;
  }
  // implicit return undefined — done: true
}

console.log([...range(0, 10, 2)]);  // [0, 2, 4, 6, 8, 10]
console.log([...range(1, 5)]);      // [1, 2, 3, 4, 5]

// ── Infinite generator: Fibonacci ───────────────────────────────
function* fibonacci() {
  let [a, b] = [0, 1];
  while (true) {          // infinite — never returns
    yield a;
    [a, b] = [b, a + b];
  }
}

// Safe consumption with take()
function take(n, iterable) {
  const result = [];
  for (const val of iterable) {
    result.push(val);
    if (result.length >= n) break;  // break calls iterator.return()
  }
  return result;
}

console.log(take(8, fibonacci())); // [0,1,1,2,3,5,8,13]

// ── yield* delegation ───────────────────────────────────────────
function* flatten(nestedIterables) {
  for (const iterable of nestedIterables) {
    yield* iterable;  // delegate to each nested iterable
  }
}

const nested = [[1, 2], [3, 4], [5]];
console.log([...flatten(nested)]);  // [1, 2, 3, 4, 5]

// ── Bidirectional: generator as coroutine ───────────────────────
function* accumulator() {
  let total = 0;
  while (true) {
    const input = yield total;  // emit total, receive next input
    if (input === null) return total;  // sentinel to end
    total += input;
  }
}

const acc = accumulator();
acc.next();         // prime: run to first yield, value=0
console.log(acc.next(10).value);  // send 10 → total=10
console.log(acc.next(5).value);   // send 5  → total=15
console.log(acc.next(null));      // { value: 15, done: true }

// ── Lazy generator pipeline: map, filter, take ──────────────────
function* mapGen(iterable, fn) {
  for (const val of iterable) yield fn(val);
}

function* filterGen(iterable, pred) {
  for (const val of iterable) {
    if (pred(val)) yield val;
  }
}

function* takeGen(iterable, n) {
  let count = 0;
  for (const val of iterable) {
    yield val;
    if (++count >= n) return;  // stops pulling from source
  }
}

// Find the first 5 perfect squares from Fibonacci numbers < 10000
function* fibonacci() {
  let [a, b] = [0, 1];
  while (true) { yield a; [a, b] = [b, a + b]; }
}

const isPerfectSquare = n => {
  const s = Math.round(Math.sqrt(n));
  return s * s === n;
};

const result = [
  ...takeGen(
    filterGen(
      fibonacci(),
      isPerfectSquare
    ),
    5
  )
];
console.log(result); // [0, 1, 1, 144, ...] — only computed what was needed

// ── Comparison: eager (wastes memory) vs lazy ───────────────────
// EAGER — bad for large/infinite data:
// const eager = fibonacci()  // would hang — infinite!
// [].slice(0, 1000).filter(isPerfectSquare).slice(0, 5);

// LAZY — correct:
// Only pulls values from fibonacci() until 5 perfect squares found.
// fibonacci() never allocates more than 2 numbers at a time.

// ── Tree traversal: iterator over a BST ─────────────────────────
class BSTNode {
  constructor(val, left = null, right = null) {
    this.val = val; this.left = left; this.right = right;
  }
}

function* inOrder(node) {
  if (!node) return;
  yield* inOrder(node.left);   // recurse left sub-tree
  yield node.val;              // emit current
  yield* inOrder(node.right);  // recurse right sub-tree
}

const tree = new BSTNode(4,
  new BSTNode(2, new BSTNode(1), new BSTNode(3)),
  new BSTNode(6, new BSTNode(5), new BSTNode(7))
);

console.log([...inOrder(tree)]); // [1, 2, 3, 4, 5, 6, 7]
// No manual stack management — the generator call stack IS the traversal stack!

// ── Async generator: paginated API cursor ───────────────────────
async function* paginatedFetch(baseUrl) {
  let page = 1;
  while (true) {
    const response = await fetch(`${baseUrl}?page=${page}&limit=100`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();

    // yield* each item individually — consumer sees a flat stream
    yield* data.items;

    if (!data.hasMore) return;   // done: true when no more pages
    page++;
  }
}

// Consumer: no pagination logic whatsoever
async function processAllProducts() {
  let count = 0;
  for await (const product of paginatedFetch('/api/products')) {
    await saveToDatabase(product);
    count++;
    if (count >= 500) break;  // early exit: return() called on generator
  }
  console.log(`Processed ${count} products`);
}

// ── Node.js: process large file line by line ────────────────────
import { createReadStream } from 'fs';
import { createInterface } from 'readline';

async function* readLines(filePath) {
  const fileStream = createReadStream(filePath);
  const rl = createInterface({ input: fileStream });
  try {
    for await (const line of rl) {  // readline is already async iterable
      yield line;
    }
  } finally {
    rl.close();  // cleanup runs even on break
  }
}

async function countNonEmptyLines(filePath) {
  let count = 0;
  for await (const line of readLines(filePath)) {
    if (line.trim()) count++;
  }
  return count;
}

// ── Async generator with cleanup (return() protocol) ────────────
async function* dbCursor(query) {
  const cursor = await db.query(query).cursor();
  try {
    let row;
    while ((row = await cursor.read(1)) !== null) {
      yield row;
    }
  } finally {
    await cursor.close();  // always runs: normal end, break, or throw
  }
}

